Definition strchr_entry : Z := 0x203ee8.

(* [comment removed for export] *)
Definition lit8 (zs : list Z) : list byte := map (Z_to_bv 8) zs.
Definition LIT8 : list (list byte) := [ lit8 [43; 0; 0; 0; 0; 0; 0; 0]; lit8 [32; 10; 9; 0; 0; 0; 0; 0] ].   (* [comment removed for export] *)

(* [comment removed for export] *)
Fixpoint scan_res (s c : Z) (bs : list Z) : Z :=
  match bs with [] => 0 | b :: r => if Z.eqb b c then s else if Z.eqb b 0 then 0 else scan_res (s + 1) c r end.
Definition strchr_res (s c : Z) (bs : list byte) : Z := scan_res s c (map bv_unsigned bs).

Definition strchr_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (r lo : Z) (m : word -> option byte) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 r) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(bv_unsigned sp - 32, bv_unsigned sp)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp).

