  a0 = Z_to_bv 64 s -> (bv_unsigned a1) mod 256 = c -> 0 < c ->
  In w8 LIT8 -> bytes_at asegs m s w8 -> s mod 8 = 0 -> 0 < s -> s + 8 <= lo ->
  stk asegs m lo (bv_unsigned sp) -> lo <= bv_unsigned sp - 32 -> bv_unsigned sp <= 2 ^ 47 ->
  mem_inv asegs m ->
  evt asegs (strchr_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc (strchr_res s c w8) lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 strchr_entry) fc None m (seg_rom asegs)).
Proof.
